-- ----------------------------
-- Table structure for evaluations
-- ----------------------------
DROP TABLE IF EXISTS `evaluations`;
CREATE TABLE `evaluations`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parent_id` int NULL DEFAULT NULL COMMENT '父级评论ID',
  `commenter_id` int NULL DEFAULT NULL COMMENT '评论者ID',
  `replier_id` int NULL DEFAULT NULL COMMENT '回复者ID',
  `content_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '内容类型',
  `content_id` int NULL DEFAULT NULL COMMENT '内容ID',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '评论内容',
  `create_time` datetime NULL DEFAULT NULL COMMENT '评论时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of evaluations
-- ----------------------------
INSERT INTO `evaluations` VALUES (19, NULL, 61, NULL, 'HEALTH-NEWS', 1, '老祖宗留下的经验，每天一个蛋，确实很有精神。', '2026-03-08 20:51:21');
INSERT INTO `evaluations` VALUES (20, 19, 60, NULL, 'HEALTH-NEWS', 1, '确实，蛋黄胆固醇高，中老年人还是要控制一下。', '2026-03-08 20:53:18');
INSERT INTO `evaluations` VALUES (21, NULL, 59, NULL, 'HEALTH-NEWS', 1, '对于我们健身的人来说，一个蛋白可能不够，我通常吃三个，但只吃一个蛋黄。', '2026-03-08 20:54:13');
INSERT INTO `evaluations` VALUES (22, NULL, 59, NULL, 'HEALTH-NEWS', 8, '冬季有氧容易感冒，一定要注意热身。', '2026-03-08 20:56:13');
INSERT INTO `evaluations` VALUES (24, 22, 62, NULL, 'HEALTH-NEWS', 8, '赞同！尤其是室外跑步，呼吸道保护很重要。', '2026-03-08 20:57:36');
INSERT INTO `evaluations` VALUES (25, NULL, 62, NULL, 'HEALTH-NEWS', 17, '这个好吃', '2026-03-08 20:58:49');

