-- ----------------------------
-- Table structure for health_goal
-- ----------------------------
DROP TABLE IF EXISTS `health_goal`;
CREATE TABLE `health_goal`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `type` int NOT NULL COMMENT '目标类型：1-减肥，2-增肌',
  `current_value` double(10, 2) NOT NULL COMMENT '当前值（体重kg 或 体脂率%）',
  `target_value` double(10, 2) NOT NULL COMMENT '目标值（体重kg 或 体脂率%）',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `status` int NULL DEFAULT 0 COMMENT '状态：0-进行中，1-已完成，2-未完成',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '健康目标表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of health_goal
-- ----------------------------
