-- ----------------------------
-- Table structure for health_model
-- ----------------------------
DROP TABLE IF EXISTS `health_model`;
CREATE TABLE `health_model`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '健康模型表主键ID，自增',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '模型名',
  `detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '模型简介',
  `icon_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '图标',
  `unit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '单位',
  `symbol` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '符号',
  `normal_value` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '正常值范围，以英文逗号“,”进行分割',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `is_global` tinyint(1) NULL DEFAULT NULL COMMENT '是否是全局模型',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '健康模型表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of health_model
-- ----------------------------
INSERT INTO `health_model` VALUES (2, '心率', '心率是指心脏每分钟跳动的次数，是反映心血管功能的重要指标。正常成年人静息状态下心率一般在 60-100 次 / 分钟，运动员或长期锻炼者可能偏低，属于正常现象', '/api/v1.0/self-health-api/file/getFile?fileName=1753597325751rate.png', '次 / 分钟', 'HR', '60,100', 1, 0, '2026-01-27 14:22:07');
INSERT INTO `health_model` VALUES (4, '体重', '体重是反映人体骨骼、肌肉、脂肪等组织总量的指标，受年龄、性别、身高等因素影响。保持健康体重可降低糖尿病、心血管疾病等患病风险，建议定期监测并结合体脂率综合评估。', '/api/v1.0/self-health-api/file/getFile?fileName=1753670454370weight.png', '千克（kg）', 'BW', '50,90', 62, 1, '2026-01-28 10:41:42');
INSERT INTO `health_model` VALUES (5, '睡眠时长', '睡眠时长指全天累计睡眠的时间，成年人正常范围为 7-9 小时。充足的睡眠有助于恢复体力、巩固记忆、调节情绪，长期睡眠不足可能导致免疫力下降、注意力不集中等问题。', '/api/v1.0/self-health-api/file/getFile?fileName=1753670667959s1.png', '小时（h）', 'ST', '7,9', 62, 1, '2026-01-28 10:44:44');
INSERT INTO `health_model` VALUES (6, '身体质量指数（BMI）', 'BMI 是评估人体胖瘦程度和健康风险的指标，偏瘦：BMI ＜ 18.5，正常：18.5 ≤ BMI ≤ 23.9，超重：24.0 ≤ BMI ≤ 27.9，肥胖：BMI ≥ 28.0', '/api/v1.0/self-health-api/file/getFile?fileName=1753760115590BMI.png', '(该模型暂无数值单位)', 'BMI', '18.5,23.9', 1, 0, '2026-01-29 11:36:06');
INSERT INTO `health_model` VALUES (9, '血压【低压】', '血液在血管内流动时对血管壁的压力，分收缩压和舒张压', '/api/v1.0/self-health-api/file/getFile?fileName=1754393475022press.png', '毫米汞柱', 'BP', '60,90', NULL, 0, '2026-01-05 19:32:33');
INSERT INTO `health_model` VALUES (10, '血压【高压】', '血液在血管内流动时对血管壁的压力，分收缩压和舒张压', '/api/v1.0/self-health-api/file/getFile?fileName=1754393568189press.png', '毫米汞柱', 'BP', '90,140', NULL, 0, '2026-01-05 19:33:15');
INSERT INTO `health_model` VALUES (11, '血糖', '血液中的葡萄糖浓度，反映人体糖代谢水平', '/api/v1.0/self-health-api/file/getFile?fileName=1754393779064xt.png', '毫摩尔 / 升', 'BG', '3.9,6.1', NULL, 0, '2026-01-05 19:36:52');
INSERT INTO `health_model` VALUES (12, '血氧饱和度', '血液中氧气结合血红蛋白占总血红蛋白的百分比', '/api/v1.0/self-health-api/file/getFile?fileName=1754393859179xy.png', '%', 'SpO₂', '95,100', NULL, 0, '2026-01-05 19:38:04');
INSERT INTO `health_model` VALUES (13, '体脂率', '身体脂肪重量占总体重的百分比，评估肥胖程度的重要指标', '/api/v1.0/self-health-api/file/getFile?fileName=1754393935430xy.png', '%', 'BF%', '18,25', NULL, 0, '2026-01-05 19:39:11');
INSERT INTO `health_model` VALUES (14, '午休时长', '午休时长，最佳睡眠时长半小时左右', '/api/v1.0/self-health-api/file/getFile?fileName=1754394071265s1.png', '小时（h）', 'ST', '0.5,0.6', 1, 0, '2026-01-05 19:40:56');

-- ----------------------------
-- Table structure for health_news
-- ----------------------------
DROP TABLE IF EXISTS `health_news`;
CREATE TABLE `health_news`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '健康资讯主键ID，自增',
  `type_id` int NULL DEFAULT NULL COMMENT '资讯分类ID，外键，资讯分类通过后端枚举类进行管理',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '资讯封面',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '内容',
  `summary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '摘要',
  `create_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '健康资讯表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of health_news
-- ----------------------------
INSERT INTO `health_news` VALUES (1, 5, '/api/v1.0/self-health-api/file/getFile?fileName=17727758684245.webp', '建议你每天吃一个鸡蛋', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>01</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>每天一个鸡蛋有助健康</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">上述研究纳入8756名70岁及以上的参与者，其中2.6%的人每天吃鸡蛋，73.2%的人每周吃鸡蛋，24.2%的人很少吃鸡蛋。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">研究人员随访5.9年后发现：与不吃鸡蛋的人相比，每周食用1—6个鸡蛋的人，无论是水煮蛋，还是煎蛋，心血管疾病死亡风险、全因死亡风险分别降低29%、15%。</span></p><p style=\"text-align: left;\"><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727759121405.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727759121405.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727759121405.webp\" style=\"width: 100%;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">在不同人群身上，鸡蛋也有不同影响。另一项研究发现，每周摄入5个及以上鸡蛋，2型糖尿病、高血压风险分别降低28%、32%。如果饮食保证均衡搭配，健康效益会更明显。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">还有一项来自广州的病例对照研究显示，每天吃1个鸡蛋有助降低痴呆风险。肥胖人群早餐吃1个鸡蛋不仅能增加饱腹感、降低餐后血糖，还可减少午餐及一整天的热量摄入。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>02</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>实至名归的“全营养食物”</strong></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">有媒体将鸡蛋称作</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">“世界上最营养的早餐”</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">这个说法并非夸张</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>一个鸡蛋几乎集齐了</strong></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>生命发育所需的营养素</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●完美蛋白质模式</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">中国疾病预防控制中心营养与健康所老年与临床营养室主任张坚表示，每个鸡蛋有6—7克蛋白质，含人体需要的全部必需氨基酸，且与人类蛋白质的氨基酸组成相近，吸收率高达99.5%，堪称“完美蛋白质模式”。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>● 维生素的“全家桶”</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">鸡蛋含多种维生素，比如水溶性的维生素B2、B9（叶酸）、B12，脂溶性的维生素A、E、K等，且国人维生素A、B2普遍摄入不足，吃一个鸡蛋就可补充每日所需的至少10%。鸡蛋还是少数天然含有维生素D的食物。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>● 胆碱为脑力加油</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">胆碱是合成乙酰胆碱的重要原料，对大脑、神经系统发育至关重要，但人体无法自行合成足够的量来满足日常所需，需要食物补充。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">专家表示，1个鸡蛋中的胆碱为176毫克，两个便接近摄入需求。孕期、哺乳期妇女适量摄入鸡蛋，有助孩子的脑发育，儿童青少年适量食用鸡蛋可提高记忆力和注意力。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●叶黄素护视力</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">东南大学附属中大医院临床营养科主任金晖表示，叶黄素、玉米黄素等抗氧化物质，可帮助视网膜免受自由基的损害，降低患白内障、黄斑变性的风险，这些人体无法自行合成，只能通过外界摄取，鸡蛋便是一个很好的来源。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>● 丰富的优质脂肪</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">1个鸡蛋的脂肪含量约5克，主要集中在蛋黄里：其中含有欧米伽3脂肪酸等不饱和脂肪酸；卵磷脂含量丰富，属于高密度脂蛋白的重要成分，可促进脂肪和胆固醇的代谢，避免胆固醇在血管壁沉积，是血脂调控的帮手。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">此外，维生素A、D、E以及叶黄素、玉米黄质，均为脂溶性营养素，配合蛋黄才能被高效吸收。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>03</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>哪些人要控制鸡蛋的摄入量</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●正常成年人，建议每天吃1个鸡蛋（包括蛋黄）</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">首先，我国居民膳食指南中建议，正常成年人每周应摄入280～350克蛋类，以一个鸡蛋50～60克计算，大约是每周吃6～7个鸡蛋，也就是</span><span style=\"font-size: 16px;\"><strong>每天1个蛋</strong></span><span style=\"font-size: 16px;\">。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●孕期、哺乳期、青春期学生、健身增肌和大病初愈恢复期的人士，建议一天最多吃3个鸡蛋</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">对于孕期、哺乳期妇女，以及处于青春期的中学生、健身增肌和大病初愈恢复期的人来说，他们对优质蛋白质的需求往往比普通人更大，将鸡蛋作为补充优质蛋白的来源是很好的方式。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">如果日常饮食中动物性食物的比例不大，只要注意鸡蛋的烹饪方式，</span><span style=\"font-size: 16px;\"><strong>采取蒸、煮等少油无油方式</strong></span><span style=\"font-size: 16px;\">，每天吃2～3个鸡蛋问题不大。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●高血脂人群，要注意控制脂肪总摄入量，其中鸡蛋建议一天不超过1个，一周不超过5个</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">对于高血脂人群来说，他们的脂类代谢已经出现了问题，对于食物来源的胆固醇和体内自我合成胆固醇的调节能力比不上正常人，因此对于胆固醇的摄入要格外敏感一些。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">根据卫健委发布的《成人高脂血症食养指南（2023）》，</span><span style=\"font-size: 16px;\"><strong>高胆固醇血症者每天胆固醇摄入量应该控制在200毫克以内</strong></span><span style=\"font-size: 16px;\">。也就是说，吃1个鸡蛋就可能会面临胆固醇摄入超标的风险。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">如果这类人群日常饮食中其他高胆固醇的食物，如动物内脏（脑、肝、心）、红肉（猪牛羊）、虾等不算太多，也没有摄入太多油脂（尤其是动物油脂和高油的加工食品），那么建议</span><span style=\"font-size: 16px;\"><strong>每天吃不超过1个鸡蛋</strong></span><span style=\"font-size: 16px;\">。如果摄入了比较多的高胆固醇食物，那就要相应控制鸡蛋的摄入，比如吃半个，或者只吃2/3的蛋黄。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>●肥胖人群，要注意控制总膳食摄入量，包括鸡蛋</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">对于有肥胖问题的人群来说，需要控制饮食热量和脂肪的摄入量。尽管鸡蛋的脂肪组成中饱和脂肪不算太多，但依然不建议吃太多。一项大型人群研究表明，若每周吃鸡蛋大于6个，肥胖人群的全因死亡率会有显著增加。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">最后，还想提醒大家的是，</span><span style=\"font-size: 16px;\"><strong>除了关注吃鸡蛋的量，记得同时要注意鸡蛋的烹饪方式（尽量采用蒸煮等方式加工鸡蛋，避免煎炸蛋）</strong></span><span style=\"font-size: 16px;\">，以及饮食整体搭配是否合理。</span></p>', '鸡蛋\n\n不仅是厨房里的百搭食材\n\n还含有人体所需的多种营养素\n\n被誉为“全营养食物”\n\n近日，一项新研究发现\n\n每周食用1—6个鸡蛋\n\n可显著降低心血管疾病死亡风险', '2026-01-26 20:58:36');
INSERT INTO `health_news` VALUES (7, 1, '/api/v1.0/self-health-api/file/getFile?fileName=17727762208056.webp', '科学、温和、规律的有氧运动 ', '<p style=\"text-align: left;\">特发性震颤人群不仅适合做有氧运动，而且科学、温和、规律的有氧，是改善身体状态、减轻抖动影响、提升生活质量的重要辅助方式。核心不在于“多练”，而在于“练对”，只要把握好运动原则，就能在安全的前提下，让运动成为稳定症状的帮手，而不是负担。<br><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727762426316.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727762426316.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727762426316.webp\" style=\"width: 100%;\"></p><p style=\"text-align: left;\">最适合特发性震颤的有氧运动，必须满足几个条件：强度低、节奏稳、动作舒缓、环境安全、不需要高度精准发力。快走是首选，简单易行、场地限制小、节奏可控，在平坦路面匀速行走，既能促进血液循环，又不会给肌肉和神经带来额外压力。慢跑要以极慢配速进行，以呼吸平稳、能正常交谈为标准，避免急促、冲刺式跑动，减少身体晃动和神经紧张。固定自行车、室内慢游泳同样友好，环境封闭、地面平稳、外力干扰少，出现轻微抖动时也不容易失去平衡，安全性更高。</p><p style=\"text-align: left;\">传统养生类运动如太极拳、八段锦、舒缓瑜伽，对特发性震颤尤为友好。这类运动强调缓慢、连贯、配合呼吸，动作幅度适中、不需要快速变换，既能增强肌肉力量和身体协调性，又能帮助放松神经、平复情绪，减少因紧张导致的抖动加重。就像慢慢调整一台运转不够平稳的设备，用柔和、持续的节奏引导它逐渐规律，远比强行控制更有效、更安全。</p><p style=\"text-align: left;\">运动时要严格避开高强度、高爆发力、高精准要求的项目，比如快速跑、激烈球类、高强度间歇训练、负重冲刺等，这些运动容易让神经高度紧张、肌肉突然用力，可能明显加重抖动，甚至带来跌倒、受伤风险。同时也要避免长时间静止发力、过度疲劳的运动形式，过度疲劳会降低神经控制能力，让抖动更难控制。</p><p style=\"text-align: left;\">运动时间遵循“短频、温和、持续”的原则，每次20到30分钟为宜，体力偏弱的人群可以缩短至15分钟，一天分多次完成，效果优于单次长时间运动。频率保持每周3到5次，重点是长期坚持，而非偶尔高强度锻炼。运动时机尽量选择情绪平稳、身体状态较好的时段，避开极度疲劳、精神紧张、空腹或过饱的状态，减少外界因素对抖动的影响。</p><p style=\"text-align: left;\">运动过程中如果出现抖动明显加重、头晕、心慌、肢体乏力，应立即停止休息，不要强行坚持。运动后不要立刻吹风、冲冷水、大量饮用冰水，避免刺激神经和血管，影响身体稳定。同时要明确，有氧运动是辅助调理手段，不能替代专业医疗方案，它的作用是改善整体状态、减轻症状影响，而非根治问题。</p><p style=\"text-align: left;\">总体而言，特发性震颤人群不是不能运动，而是要科学运动。选对项目、控制强度、保持规律、注重安全，有氧运动就能有效提升身体稳定性、放松神经、缓解情绪，让日常活动更轻松、抖动带来的困扰更小，在平稳与适度活动中，维持更健康、更有质量的生活状态。</p>', '科学、温和、规律的有氧运动 ', '2026-01-04 21:26:22');
INSERT INTO `health_news` VALUES (8, 1, '/api/v1.0/self-health-api/file/getFile?fileName=17727764070167.webp', '推荐一款冬季有氧运动：超慢跑，边聊天边燃脂的秘密 ', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>什么是超慢跑？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>和走路有何区别？</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">超慢跑，顾名思义就是“超级慢的跑步”，它属于一种低强度、高步频的温和有氧运动，核心特点十分鲜明：</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●速度极慢：时速约5～6公里，和快走差不多甚至更慢。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●心率可控：保持在（220-年龄）的60%～70%，无需剧烈喘息。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●体感轻松：能边跑边聊天、哼歌，全程面带微笑，毫不费力。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">很多人会疑惑：速度和走路差不多，为什么超慢跑更燃脂？关键在于腾空期——超慢跑时有双脚同时离地的瞬间，能调动臀腿等大肌群，消耗的能量比走路多1.5～2倍，减脂效果自然更优。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>冬季减脂</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么优先选超慢跑？</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>①燃脂针对性强，专克“冬膘”</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">超慢跑的心率区间能高效燃烧脂肪酸，尤其能减少冬季易堆积的腰腹脂肪，对大体重人群格外友好。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>②强度温和，不怕着凉</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">运动时体温稳定，不会大汗淋漓，避免了冬季运动后吹风受寒的风险，室内外都能开展。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>③门槛极低，说动就动</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">不用专门换运动服、不怕弄湿头发，在家穿着居家服、甚至办公室间隙就能练。心理负担小，更容易坚持。</span><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727764306197.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727764306197.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727764306197.webp\" style=\"width: 100%;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>超慢跑的正确打开方式：</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>记住“小低高”原则</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">想要练得安全又高效，核心要掌握“小步幅、低心率、高步频”的要点，再配合标准姿势→</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>1.核心三要素：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●小步幅：30～60厘米，前脚跟几乎贴近后脚尖，减少膝盖冲击。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●低心率：初期控制在150次/分以内，熟练后保持120～140次/分。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●高步频：目标170～190步/分钟，可用节拍器App辅助练习。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>2.标准姿势：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">身体挺直，想象头顶有一根线向上牵引；手臂自然弯曲90度前后摆动；双脚轻盈交替离地；呼吸推荐“四步一吸，四步一呼”，保持均匀。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>3.强度判断：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">以能完整说话、面带微笑为准，一旦感觉喘，立刻减速调整。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>阶梯式进阶计划：</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>从新手到熟练，循序渐进</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">不用急于求成，跟着这份计划慢慢提升，更容易养成习惯↓</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●第1周：超慢跑3～5分钟+快走5分钟，循环4组。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●第2周：超慢跑10分钟+快走3分钟，循环2～3组。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>●1个月后：尝试连续超慢跑20～30分钟。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>理想频率：每周3～5次，初期可采用“跑一休一”的节奏；每次运动时长30分钟以上，后期可逐步增至45～60分钟。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>重要提醒：冷天更需充分热身，运动前后做好拉伸（各5～10分钟）。始终遵循“不酸、不痛、不硬、不喘” 的原则。</strong></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>你适合超慢跑？</strong></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>哪些情况要谨慎？</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>1.特别适合：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●长期久坐的办公族。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●体重基数较大者。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●中老年人。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●慢性病患者（如高血压、糖尿病，开始前请咨询医生）。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>2.需要谨慎：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●处于急性疾病期的人群。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●有不稳定心脑血管疾病的人群。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●存在严重平衡障碍的人群。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>3.常见误区要避开：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●不在指压板等不平整地面上跑，避免受伤。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●超慢跑是理想的入门运动，体能提升后建议结合力量训练，效果更加。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">●切勿追求速度，运动时避免空腹或饱腹状态。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">这个冬天，别再让寒冷成为不运动的借口，用最温柔的“跑”，暖身、燃脂、增强体质，慢慢遇见更好的自己～</span></p>', '天气一冷，不少人就陷入“管不住嘴、迈不开腿”的循环——新陈代谢变慢，食欲反而上涨，冬季减脂似乎成了难题。但其实，有一种运动能完美适配冬天：无需顶风出门，在家就能练，对膝盖友好，燃脂效率还远超走路，它就是近期备受推崇的超慢跑。\n\n今天就带大家科普超慢跑的核心知识，帮你科学开启冬季减脂路。', '2026-01-04 21:27:29');
INSERT INTO `health_news` VALUES (9, 4, '/api/v1.0/self-health-api/file/getFile?fileName=17727754836561.webp', '为什么越努力越焦虑？两大压力激素大揭秘（皮质醇、肾上腺素） ', '<p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>皮质醇</strong></span><span style=\"font-size: 16px;\">和</span><span style=\"font-size: 16px;\"><strong>肾上腺素</strong></span><span style=\"font-size: 16px;\">是我们身体的两大压力激素来源，在远古时代，我们祖先在遇到野兽袭击、或者狩猎逃跑时，通过释放压力激素（皮质醇、肾上腺素）给身体增压，完成身体各机能的快速调动，快速消耗能量来完成危险的躲避、对狩猎的应变等等。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">这项刻在我们基因里面的远古机制，通过短时间增加压力、提升专注力，来快速完成对危机的应对，在以前很长一段时间都是一个非常有效的生存机制，然而</span><span style=\"font-size: 16px;\"><strong>步入现代社会，这项远古机制却成为了现代人长期压力拖累身体的来源。</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">不同于远古时期的压力，现代人的压力来源主要在考试、房贷、晋升、职场、人际关系等等方面，这些压力源无法像远古危机那样来的快去的也快，无法短期释放压力，导致身体就像一个一直充着电的充电宝，随时准备释放压力，但却无法释放，一直被蓄压，慢慢的身体承受不了压力，会出现损坏等健康问题。</span></p><h1 style=\"text-align: center;\"><strong>一、作用机制：身体的“应急指挥官”</strong></h1><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755439632.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755439632.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755439632.webp\" style=\"width: 100%;\"/></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>皮质醇：长效压力调节器</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">皮质醇被称为“压力激素”。它通过下丘脑-垂体-肾上腺轴（HPA轴）调控，形成精密的反馈环路：</span></p><ol><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>启动信号</strong></span><span style=\"font-size: 16px;\">：压力刺激下丘脑释放促肾上腺皮质激素释放激素（CRH），激活垂体分泌促肾上腺皮质激素（ACTH）。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>执行指令</strong></span><span style=\"font-size: 16px;\">：ACTH作用于肾上腺，促使皮质醇合成并释放入血。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>负反馈调节</strong></span><span style=\"font-size: 16px;\">：皮质醇水平升高后，会抑制CRH和ACTH分泌，防止过度反应。</span></li></ol><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">其分泌遵循昼夜节律——清晨6点达高峰，助你清醒应对挑战；午夜降至最低，支持身体修复。这种节律性确保能量供应与代谢平衡的动态调整。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>肾上腺素：急性应激反应器</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">肾上腺素由肾上腺分泌，是“战斗或逃跑”反应的核心执行者：</span></p><ol><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>快速响应</strong></span><span style=\"font-size: 16px;\">：面对突发威胁（如意外事件），交感神经系统直接激活肾上腺髓质，肾上腺素迅速释放。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>能量动员</strong></span><span style=\"font-size: 16px;\">：它通过促进糖原分解和脂肪代谢，快速提升血糖和游离脂肪酸水平，为肌肉和大脑提供即时能量。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>生理效应</strong></span><span style=\"font-size: 16px;\">：收缩血管、升高血压、加速心跳，确保关键器官获得充足供血。</span></li></ol><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">与皮质醇的长效调节不同，肾上腺素的作用更侧重于紧急状态下的生理动员。</span></p><h1 style=\"text-align: left;\"><strong>二、危害解析：压力失衡的连锁反应</strong></h1><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755994203.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755994203.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727755994203.webp\" style=\"width: 100%;\"/></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">长期压力导致皮质醇与肾上腺素持续升高，形成恶性循环：</span></p><ol><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>体重管理困境</strong></span><span style=\"font-size: 16px;\">：皮质醇促进腹部脂肪堆积，肾上腺素加速肌肉分解，共同导致代谢率下降与体重增加。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>免疫系统受损</strong></span><span style=\"font-size: 16px;\">：皮质醇抑制免疫细胞活性，肾上腺素扰乱自主神经平衡，增加慢性炎症与自身免疫疾病风险。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>心血管疾病风险</strong></span><span style=\"font-size: 16px;\">：肾上腺素升高血压与心率，皮质醇促进血管硬化，二者协同增加动脉粥样硬化与心脑血管事件概率。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>情绪与认知障碍</strong></span><span style=\"font-size: 16px;\">：激素失衡干扰神经递质平衡，导致焦虑、抑郁及记忆力减退。</span></li></ol><h1 style=\"text-align: left;\"><strong>三、调节策略：重归平衡的实用方法</strong></h1><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>1️⃣生活方式调整</strong></span></p><ul><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>规律作息</strong></span><span style=\"font-size: 16px;\">：保证每晚7-8小时睡眠，避免熬夜。睡眠不足会加剧皮质醇分泌紊乱，形成“压力-失眠”恶性循环。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>适度运动</strong></span><span style=\"font-size: 16px;\">：每周3-5次有氧运动（如快走、游泳），每次30分钟以上。运动可降低皮质醇基线水平，提升胰岛素敏感性。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>压力管理</strong></span><span style=\"font-size: 16px;\">：每日15分钟冥想或深呼吸练习，激活副交感神经系统，抑制肾上腺素过度分泌。</span></li></ul><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>2️⃣饮食干预</strong></span></p><ul><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>营养均衡</strong></span><span style=\"font-size: 16px;\">：增加富含维生素C（柑橘、彩椒）、Omega-3（深海鱼、核桃）及B族维生素（全谷物、绿叶菜）的食物摄入，支持肾上腺功能与抗炎代谢。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>控制糖盐</strong></span><span style=\"font-size: 16px;\">：减少高糖、高盐及加工食品，避免血糖波动与胰岛素干扰皮质醇代谢。</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>稳定血糖</strong></span><span style=\"font-size: 16px;\">：选择低升糖指数食物（如燕麦、豆类），避免饥饿感引发的皮质醇激增。</span></li></ul><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\"><strong>3️⃣ 医疗与机构支持</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">精神类疾病的现行技术方法对比</span></p><ul><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>无副作用：</strong></span><span style=\"font-size: 16px;\">心理咨询、多光谱治疗仪</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>治疗周期（短到长）</strong></span><span style=\"font-size: 16px;\">：多光谱治疗仪、电疗、经颅磁治疗仪、光照疗法、药物治疗、心理咨询</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>治疗效果（高到低）</strong></span><span style=\"font-size: 16px;\">：多光谱治疗仪、药物治疗、电疗、光照疗法、经颅磁治疗仪、心理咨询（效果不确定）</span></li><li style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>患者接受度（高到低）</strong></span><span style=\"font-size: 16px;\">：心理咨询、多光谱治疗仪、光照疗法、药物治疗</span></li></ul>', '为什么越努力越焦虑？两大压力激素大揭秘（皮质醇、肾上腺素） ', '2026-01-04 21:28:16');
INSERT INTO `health_news` VALUES (10, 5, '/api/v1.0/self-health-api/file/getFile?fileName=17727766026308.webp', '早餐最好别吃这３种食物：吸收差 ', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\">早餐，是一天之中补充营养的第一餐，更是忙碌生活中难得的享受。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">早餐这么关键，却常常有人忽略它。有人因为赶时间、减肥就不吃早餐，这种行为相当不健康；还有人明明吃了早餐，却好像没吃一样，出现胃痛、发胖、乏力等不适。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">这往往是——坏习惯、错误的认知阻碍着我们吃一顿健康的早餐。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>这样吃早餐，等于白吃</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">吃早餐的方式不正确，不仅对身体无益，还影响着一天的心情。如果你发现自己犯了以下这些误区，就要及时调改了。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">▪ 超过9点吃早餐</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">其实我们吃早餐的最佳时间是</span><span style=\"font-size: 16px;\"><strong>早上的6点至8点</strong></span><span style=\"font-size: 16px;\">，因为这时胃酸分泌旺盛，进食对肠胃最好。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">如果是超过9点吃早餐，就有可能会导致午餐没有食欲、胃口不佳。即使过了9点也要吃早餐，同样能够补充营养，只是吸收相对差而已。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>太早吃早餐会干扰肠胃的休息，扰乱肠胃的蠕动节奏。</strong></span><span style=\"font-size: 16px;\">有医学专家指出，人在睡眠时，绝大部分器官都在休息，而消化器官却仍在消化、吸收存留在胃肠道的食物，到早上才渐渐进入休息状态。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">▪ 用非主食代替早餐</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">相信不少朋友都试过早餐随便吃，认为只要填饱肚子就可以。这样做，营养和健康都会出问题。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>错误1：水果代替早餐</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">有些女性朋友为了减肥，就用水果来当早餐。这样的早餐既缺乏供给大脑能量的糖原（主食等碳水化合物），又缺乏能使人保持旺盛精力的蛋白质，长期下去会引起多种营养素的缺乏。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>错误2：零食代替早餐</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">人在早上是处于脱水的状态，且零食属于干食，若用零食代替早餐，会影响肠胃消化。虽然饼干能在短时间内提供能量，但是饥饿感来得更快，还没到中午，血糖就会明显下降。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>错误3：即食面代替早餐</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">即食面是一种脂肪含量较高的食物，经常用方便面当早餐易引发肠胃问题。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">▪ 边走边吃有吸入细菌的风险</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">上班一族边走边吃早餐，其实这样吃早餐是有健康风险的。在路上解决早餐，</span><span style=\"font-size: 16px;\"><strong>很容易将空气中的尘埃、微生物、有害气体吃到肚子里</strong></span><span style=\"font-size: 16px;\">，不仅不卫生，还影响健康。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">加之，走路的频次、幅度都会</span><span style=\"font-size: 16px;\"><strong>影响肠胃的消化和吸收</strong></span><span style=\"font-size: 16px;\">。当身体忙于应付耗费较大的肌肉活动时，血液供应会从胃肠等消化系统转移到肌肉，由此引起消化不良。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">▪ 早餐吃太快伤胃</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">狼吞虎咽地吃早餐会加重肠胃负担，产生消化不良。所以，千万别为了贪快或肚子饿，而猛吃一顿。吃早餐就应该</span><span style=\"font-size: 16px;\"><strong>细嚼慢咽</strong></span><span style=\"font-size: 16px;\">，好好享受早餐的时光。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>长期不吃早餐，身体发生惊人变化</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">“不吃早餐不健康”这一个道理，大家都懂。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">长期不吃早餐，身体的外形会慢慢发生变化，其中最明显的变化是</span><span style=\"font-size: 16px;\"><strong>发胖</strong></span><span style=\"font-size: 16px;\">。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">经常不吃早餐的人还会呼出难闻的气味——</span><span style=\"font-size: 16px;\"><strong>口臭</strong></span><span style=\"font-size: 16px;\">。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">早上要坚持吃早餐，同时还需要认真刷牙，保持口腔的清洁，抑制发挥性硫化物产生，抑制口臭。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">不吃早餐还会损害我们的身体器官，响起疾病的信号灯。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>怎样才算是一顿健康的早餐呢？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">想吃一顿健康的早餐不难，重点在于营养搭配。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">遵循</span><span style=\"font-size: 16px;\"><strong>“均衡、多样、少油”</strong></span><span style=\"font-size: 16px;\">的原则，一顿健康又营养的早餐就诞生了。针对不同的人群，做了一份营养早餐的清单，大家可以根据需求选择合适自己的早餐！</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>▶ 学生党：营养全面</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">学生正是长身体的时候，早餐应当全面、丰富，各种营养素都要摄入。最常见的早餐搭配就是牛奶和鸡蛋，但是学生仅仅这样吃是不够的，应该搭配面包、面条、粥等主食和新鲜的水果。</span><span style=\"font-size: 16px;\"><strong>注意，喝完牛奶不要马上吃水果，要间隔半小时再吃。</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>▶ 上班一族：针对性补充</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">大多数上班一族都经常久坐，运动量少，适当在早餐中添加</span><span style=\"font-size: 16px;\"><strong>全麦面包、杂粮粥</strong></span><span style=\"font-size: 16px;\">，可以避免脂肪增长。上班族的早餐不要过于油腻，如油条、油炸大饼这类，可在早餐中加入少量的</span><span style=\"font-size: 16px;\"><strong>坚果</strong></span><span style=\"font-size: 16px;\">，其含有不饱和脂肪酸对心脏健康有帮助。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>▶ 40~59岁中年群体：高纤低脂</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">到了中年时期，人开始衰老，身材也容易走样。中年人最好是吃低热量、低脂肪的食物做早餐，适当控制碳水化合物的摄入量。所以，小健认为中年人比较理想的早餐搭配是：</span><span style=\"font-size: 16px;\"><strong>燕麦粥（酸奶）+全麦面包+适量的蔬菜（玉米）</strong></span><span style=\"font-size: 16px;\">。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>▶ 60岁以上的老年人：清淡易消化</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">这一年龄段的老人，各器官逐渐衰老，其消化系统相对较弱、味觉也下降，早餐一般选择清淡、软且易消化的食物比较好。粥类可以选择</span><span style=\"font-size: 16px;\"><strong>瘦肉粥、青菜粥、胡萝卜粥（护眼）</strong></span><span style=\"font-size: 16px;\">，主食选择</span><span style=\"font-size: 16px;\"><strong>馒头、包子</strong></span><span style=\"font-size: 16px;\">，可搭配</span><span style=\"font-size: 16px;\"><strong>鸡蛋</strong></span><span style=\"font-size: 16px;\">补充蛋白质。</span></p>', '早餐最好别吃这３种食物：吸收差 ', '2026-01-04 21:28:57');
INSERT INTO `health_news` VALUES (11, 3, '/api/v1.0/self-health-api/file/getFile?fileName=177277733703011.webp', '睡眠障碍知多少：你的睡眠真的健康吗？ ', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>认识几个“夜间捣蛋鬼”</strong></span></p><ol><li style=\"text-align: left;\">失眠：最常见。不只是“睡不着”，而是指长期（超过三个月）难以入睡、容易醒或醒得太早，并且严重影响了你白天的精神状态和工作生活。你的大脑像装了个关不掉的警报器，持续紧张。</li><li style=\"text-align: left;\">睡眠呼吸暂停：隐形的健康杀手。打呼噜声音巨大且不规律，打着打着突然没声了（憋气十几秒甚至更久），然后猛吸一口气。这一夜，你的身体在“窒息-惊醒”中反复循环几百次，心脏和大脑承受着巨大压力。很多人白天困得不行，却不知道夜里经历了什么。</li><li style=\"text-align: left;\">发作性睡病：白天像被“突然断电”，在任何时间、任何场合（比如吃饭、说话时）都可能无法抗拒地秒睡。有时还会出现“情绪一激动就腿发软”的情况。这不是懒惰，是大脑缺少一种维持清醒的物质。</li><li style=\"text-align: left;\">快速眼动睡眠行为障碍：通常，我们做梦时身体是“瘫痪”的，很安全。但有的人却在梦境中“动手动脚”，比如拳打脚踢、大声喊叫。这不仅是睡眠问题，更是神经系统的一个早期预警信号。</li><li style=\"text-align: left;\">不宁腿综合征：晚上一躺下，两条腿就像有蚂蚁在爬、被拉扯，产生一种必须动一动的强烈欲望。必须下床走走才能缓解，严重干扰入睡。</li></ol><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么睡眠会“叛变”？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">我们的睡眠由大脑精密调控，像一场精心编排的交响乐。但当压力、焦虑、不良生活习惯或身体疾病等“不和谐音”出现时，这场音乐会就可能乱套。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">现代生活无疑是睡眠障碍的“催化剂”。蓝光屏幕偷走了我们的褪黑素，24小时不间断的信息流让大脑难以放松，咖啡因和酒精错误地成了“助眠剂”，而不规律的作息时间则彻底打乱了身体的生物钟。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>看不见的健康代价</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">睡眠障碍不只是让你白天打哈欠那么简单。长期睡眠不足或质量差，就像在身体里埋下了无数颗“健康炸弹”：</span></p><ul><li style=\"text-align: left;\">你的记忆力会悄悄衰退，就像硬盘有了坏道</li><li style=\"text-align: left;\">免疫系统变得迟钝，更容易被疾病侵袭</li><li style=\"text-align: left;\">心血管系统承受额外压力，高血压、心脏病风险增加</li><li style=\"text-align: left;\">情绪调节器失灵，焦虑和抑郁的风险显著升高</li><li style=\"text-align: left;\">代谢紊乱，体重悄悄增加，糖尿病风险上升</li></ul><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">更可怕的是，有些睡眠障碍本身就是“隐形杀手”。严重睡眠呼吸暂停患者猝死风险是正常人的三倍以上。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>科学的应对步骤</strong></span></p><ol><li style=\"text-align: left;\">观察记录：别急着自己乱吃药，用一两周时间，简单记录：几点上床、多久睡着、夜里醒几次、早上几点醒、白天精神如何。这是给医生最重要的线索。</li><li style=\"text-align: left;\">看对科室：去正规医院的“睡眠门诊” 或 “神经内科” 、“呼吸内科”（如果怀疑打呼噜憋气），寻求帮助。</li><li style=\"text-align: left;\">接受关键检查——睡眠监测。</li></ol><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">通过睡眠监测仪记录下整夜的脑电、心电、呼吸、血氧等，进而辅助医生进行病情判断。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>给所有人的“ 睡眠处方 ”</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">无论你有没有睡眠问题，这些好习惯都能提升睡眠质量：</span></p><ul><li style=\"text-align: left;\">固定作息：每天同一时间起床（包括周末），是调节生物钟最有效的方法。</li><li style=\"text-align: left;\">卧室只用来睡觉：别在床上玩手机或者工作，让大脑形成“床=睡觉”的条件反射。</li><li style=\"text-align: left;\">创造黑暗凉爽的环境：拉好遮光窗帘，室温调低一点（约20℃最佳）。</li><li style=\"text-align: left;\">睡前“断电”一小时：远离手机、电脑屏幕的蓝光，可以看书（纸质）、听轻音乐。</li><li style=\"text-align: left;\">警惕咖啡因和酒精：下午就不喝咖啡奶茶以及含酒精饮品，虽然酒精有可能让人入睡快，但会严重破坏后半夜睡眠。</li></ul><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>自测一下自己的睡眠质量</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">如果你长期存在以下任何一条，就应该认真考虑去看睡眠医生了：</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">1.连续一个月，每周有3天以上睡不好，且白天头晕脑胀。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">2.打呼噜声巨大、不规则，白天过度困倦（坐着不动就能睡着）。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">3.家人发现你睡觉时呼吸有暂停、或者拳打脚踢。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">4.夜间腿部的难受感觉，严重影响你入睡。</span></p><p style=\"text-align: left;\"><img src=\"https://q8.itc.cn/q_70/images03/20260306/c7e42ea0871543d6a5349c10bb1359f8.jpeg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">睡眠不是奢侈品，而是生命的必需品。重视睡眠障碍，就是投资自己长期的身心健康。愿你每晚安眠，醒来神清气爽。</span></p>', '我们一生有三分之一的时间在睡觉，但很多人对这三分之一的质量却一无所知。睡眠障碍，远不只是“昨晚没睡好”那么简单，它是一系列需要被正视的健康问题。', '2026-01-04 21:29:21');
INSERT INTO `health_news` VALUES (12, 2, '/api/v1.0/self-health-api/file/getFile?fileName=17727768749829.webp', '晨跑10年，每天五六点起床，原来很简单！', '<p><span style=\"color: rgb(25, 25, 25); background-color: rgb(255, 255, 255); font-size: 16px;\">晨跑，是一种健康的生活方式，说难不难，说易不易，难在每天早起推开被窝，易在一旦养成习惯，就成了刻进骨子里的自律。身边跑圈的朋友都有个共识：能常年坚持晨跑的人，做事大多靠谱，这份自律藏着他们对生活的掌控力。</span></p><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=17727769015299.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=17727769015299.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=17727769015299.webp\" style=\"width: 100%;\"/><span style=\"color: rgb(25, 25, 25); background-color: rgb(255, 255, 255); font-size: 16px;\">当清晨的第一缕阳光照耀在脸上，你的身体开始释放出活力与热情，迅速提高你的代谢率，更有精力地应对一天的挑战。</span></p><p><img src=\"/api/v1.0/self-health-api/file/getFile?fileName=177277693097910.webp\" alt=\"/api/v1.0/self-health-api/file/getFile?fileName=177277693097910.webp\" data-href=\"/api/v1.0/self-health-api/file/getFile?fileName=177277693097910.webp\" style=\"\"/></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">在晨跑的路上，你还可以欣赏清晨的美景，呼吸清新的空气，感受大自然的美好。这不仅可以让你更加放松和愉悦，还可以让你忘却生活中的烦恼和压力，重新充满正能量。当这些健康的小习惯成自然，早晨五点多起来跑步，绝对不会是难事！</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">比如我们跑团基本上有六成以上的跑者都会选择进行早上五六点起床跑步，他们说五六点的清晨非常的安静，足以能够让自己静下来心来认真的跑完5公里或者10公里。当这些健康的小习惯成自然，下面是晨跑十年的老鸟分享：早晨五点多起来跑步，也不会是难事！</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>①.用各种方式提醒自己</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">刚开始晨跑，总是很难打败被窝。这时候该怎么下定决心？很简单，多上称，多照镜子！不要总是窝在沙发看手机，记录下自己的初始体重，每周一测，就能刺激到你想继续跑步的决心~</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>②.提前查看天气</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">提前查看天气，可以做好准备工作，也能避免“看起来天气不好，要不今天不跑了”的念头。注意是否有风雨、寒潮霜雪等，备好第二天的衣物，如果空气不好还可以考虑加上一个口罩。</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>③.设备充满电</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">不管是带着手机还是GPS手表跑步，或者是蓝牙耳机，都一定要记得睡前充电，以免第二天早晨发现电量不足，又来不及充电，早起的时间又白白浪费。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">到后期习惯了路程之后，其实也可以不带设备，掐着距离回家就行，速度平稳的情况下，时间不会和计划里相差太多。</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>④.按摩和拉伸</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">睡前抽出15-20分钟的时间，利用泡沫轴进行自我按摩，并进行拉伸，可以让身体得到放松，改善身体的活动幅度，有利于促进睡眠。休息好才能训练更好。<br></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>⑤.睡前关闭电子设备</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">睡前至少1个小时就关闭所有的电子产品，包括电视、手机、平板、电脑等，防止沉迷其中而忘记休息的时间。此时可以听听广播或者音乐，或者看看书，为睡眠创造一个良好的环境。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">要知道，手机屏幕的蓝光还会影响褪黑素分泌，让你越看越精神。要想早起，第一个就是遵从生理规律，最迟11点也要入睡，保证6-8小时睡眠。</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>⑥.晨跑前补充体能</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">人体在早晨的状态比较特别，一是晚上丢失水分很多，水分不足，血液黏稠度高；二是较长的时间没有进食，血糖很低。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">这两个因素是影响跑步效果以及兴奋度的根本原因。晨跑之前，需要先解决它们，就要求我们及时补水——早上起床第一件事就是喝一杯150-200ml的净水，在半小时内补水400ml左右。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">补糖，跑步前可以吃一些易于消化的食物，如直冲麦片，面食等等。根据实际情况摄取，如果你跑30分钟，150-200克就很好了。</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\"><strong>⑦.每次跑步控制时间</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">可以刚开始不要起的太早，每次晨跑的时间也不设定太长，免得还没开始就产生挫败感，从而让你对整件事都反感起来。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">先从早起开始，试着跑15分钟20分钟，等能坚持下去了，再延长跑步的时间。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">晨跑虽好，身体处于不适或免疫力低下时，切勿晨跑，有可能会加重病情。每次跑完冷身后，要注意保暖，防止着凉。最后，早餐最好安排在运动结束半小时后，饮食以清淡为主，可适量增加蛋白质的摄入。</span></p><p style=\"text-align: left;\"><span style=\"color: rgb(25, 25, 25); background-color: rgb(255, 255, 255); font-size: 16px;\">坚持晨跑的背后，藏着的是一系列优秀的小习惯，</span><span style=\"color: rgb(25, 25, 25); background-color: rgb(255, 255, 255); font-size: 16px;\"><strong>也许你目前做不到，但是，从这些小事入手，慢慢你也会变成自己眼中的“大神”</strong></span></p>', '晨跑10年，每天五六点起床，原来很简单！', '2026-02-05 19:20:00');
INSERT INTO `health_news` VALUES (13, 4, '/api/v1.0/self-health-api/file/getFile?fileName=177277763756612.webp', '我如何学会与情绪共处？抑郁症康复者的6个实用心得。', '<p><br></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">抑郁症康复是一个漫长且充满挑战的过程，而学会与情绪共处是其中至关重要的一环。许多康复者发现，单纯依赖药物治疗并不能完全地解决情绪问题，而心理调节与自我觉察同样必不可少。作为一名曾经历过重度抑郁症并逐渐走出困境的人，我总结了6个实用的心得。帮助自己更好的理解和应对情绪，这些方法基于心理学的研究和自身经验，希望对同样在情绪困扰中挣扎的你有所启发。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">要承认情绪的存在，而不是对抗。许多人面对负面情绪的第一反应就是逃避、压抑或者否认。我们误以为坚强就是不感受痛苦，实际上真正的韧性来自于接纳，而不是对抗。抑郁症康复的关键，第一步是允许自己感受情绪，而不是将其视为敌人。当情绪压抑时，大脑的情绪中心如杏仁核会变得更加活跃。反而加深负面情绪的深度，相反承认情绪的存在可以减少它的困扰性。你可以尝试对自己说，我现在感到痛苦、沮丧、焦虑，但是这很正常。这种接纳态度有助于减少情绪带来的身心负担。</span></p><p style=\"text-align: center;\"><img src=\"https://q1.itc.cn/images01/20260228/dcbb7d047c0741fdb834853c19717faf.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">学会情绪命名与觉察。情绪往往像一团乱麻，混杂着愤怒、悲伤、无助或者孤独。学会精准命名情绪，可以帮助你更好地理解自己。心理学家称之为情绪粒度，情绪分辨能力越强的人，情绪调节能力越佳。你可以写下当前的情绪，如我感到沉重，而不是非常简单的难受。使用情绪轮盘工具细化情绪词汇，如失望、自责、迷茫。记录情绪的出发点，观察它们与身体感受的关联，觉察情绪的本质，你才能更理解的对待它。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">要建立情绪行动的缓冲带。抑郁症容易陷入思维反刍，不断回忆痛苦的事件，并加剧负面情绪。所以要在情绪与行动之间创造一个缓冲空间，尤为重要。具体可以暂停判断，情绪激烈时先深呼吸几次，问自己这个想法是事实，还是我的解读？延迟决策。如果情绪冲动驱使你做出极端行为，如自我伤害、愤怒发泄，先告诉自己，我等10分钟再决定。短暂切换到低刺激活动，如整理房间、散步，给情绪冷却时间。情绪会消散，但冲动的行为可能造成难以挽回的后果。</span></p><p style=\"text-align: center;\"><img src=\"https://q2.itc.cn/images01/20260228/71a7a42dab1e436fa0b844d6eac5de7b.jpeg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">用身体感受调节情绪。情绪不仅是心理活动。还伴随强烈的身体反应。抑郁症患者常出现身体僵硬、疲劳、胸口沉闷等症状。通过身体调节情绪是一种科学的、有效的方法。尝试478呼吸法。要适度运动，释放压力，缓解焦虑。轻度有氧运动如快走能促进内啡肽分泌，改善情绪。关注身体各部位的感受，减少情绪对身体的控制。身体放松时，情绪的强度也随之降低。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">要学会练习自我关怀。抑郁症康复过程中，很多人会陷入自我指责，为什么我这么脆弱？为什么别人能快乐而我不能？这些想法只会加深痛苦。要学会练习自我关怀。抑郁症康复过程中，很多人会陷入自我指责，为什么我这么脆弱？为什么别人能快乐而我不能？这些想法只会加深痛苦。心理学家提出自我关怀，强调像对待朋友一样对待自己。学会接纳不完美，允许自己有糟糕的情绪，告诉自己这是人之常情。要减少批评，用温和的语言替代自我攻击。如现在我很难受，但我会慢慢好起来。向信任的人倾诉，或者使用自我安抚技巧，写一封安慰自己的信。自我关怀不是纵容痛苦，而是培养情绪的韧性。</span></p><p style=\"text-align: center;\"><br></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">要重新定义康复。许多人认为抑郁症的康复是完全摆脱负面情绪。回到从前快乐的样子。实际上，康复更像是学会与情绪共处，而不是完全消除它们。即使在康复后，情绪波动仍然可能发生，但这并不意味着失败。要关注微小进步，哪怕今天比昨天多了一丝平静，也值得庆祝。要接纳反复，情绪偶尔回潮是正常的，不I不代表病情恶化。心理健康不是一直快乐，而是能够灵活应对不同的情绪状态。真正的康复是不是没有悲伤，而是面对悲伤时仍能保持前行的力量。</span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">抑郁症的康复不是一蹴而就的过程，情绪管理更是一门需要持续学习的技能。希望这6个心理方法能帮助你更好地理解和应对情绪，减少它的控制力。正如心理学家荣格所说，我不是我所遭遇的，而是我选择成为的。每个情绪波动的瞬间都会重新抑郁症的康复不是一蹴而就的过程，情绪管理更是一门需要持续学习的技能。希望这6个心理方法能帮助你更好地理解和应对情绪，减少它的控制力。正如心理学家荣格所说，我不是我所遭遇的，而是我选择成为的。每个情绪波动的瞬间都是一次重新认识自我的机会。也许抑郁让你停滞，但它能成为你更深刻理解生命的契机。祝你在这条路上找到属于自己的平静与力量。</span></p>', '我如何学会与情绪共处？抑郁症康复者的6个实用心得。', '2026-01-05 19:20:52');
INSERT INTO `health_news` VALUES (14, 5, '/api/v1.0/self-health-api/file/getFile?fileName=177277784685313.webp', '喝苹果醋“刮油”、“补钾消水肿”、采用生酮饮食……节后减重，别踩坑！ ', '<p><br></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>喝苹果醋能“刮油”？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>苹果醋中的醋酸无法分解脂肪，空腹大量饮用还会损伤牙釉质、刺激胃黏膜</strong></span></p><p style=\"text-align: left;\">“大餐后水肿，吃香蕉、菠菜就好”的说法，在<span style=\"font-size: 16px;\">厦门</span>本地健身群、美食群中流传甚广。<span style=\"font-size: 16px;\">厦门弘爱医院</span>体重管理中心负责人、内分泌科主任田建卿表示，消除水肿的有效方法仍是限钠。“暴食往往伴随高盐摄入，<span style=\"font-size: 16px;\">钠离子</span>滞留会引发水肿，香蕉、菠菜等高钾食物理论上可通过钠钾交换促进钠排出，但日常生活中其辅助消肿的作用不确定。”田建卿提醒，补钾应食补优先且需适度，肾功能不全者过量食用可能引发<span style=\"font-size: 16px;\">高钾血症</span>。</p><p style=\"text-align: left;\">针对社交平台风靡的喝苹果醋“刮油”等方法，田建卿直言存在健康隐患。“所谓‘刮油’是感官错觉，苹果醋中的醋酸无法分解脂肪，空腹大量饮用还会损伤牙釉质、刺激胃黏膜，甚至导致血钾降低。”田建卿还指出，暴饮暴食后立即轻断食会加剧饥饿感，诱发下一次暴饮暴食，可能导致血糖波动，尤其不适合<span style=\"font-size: 16px;\">糖尿病</span>患者。</p><p style=\"text-align: left;\">田建卿给出了暴饮暴食后“48小时科学补救方案”：避免“躺卧即睡”；避免“补偿性”极端节食，次日恢复正常饮食，遵循“1拳主食+1掌蛋白+2拳蔬菜”配比，每天饮用1500—2000毫升温水，搭配适量<span style=\"font-size: 16px;\">益生菌酸奶</span>，帮助恢复肠道菌群平衡。</p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>生酮饮食“速效减重”？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>短期减重多为水分和糖原流失，并非真正减脂，长期维持会引发多种健康问题</strong></span></p><p style=\"text-align: left;\">“喝油吃肥肉还能瘦”——节后，生酮饮食因“速效减重”标签登上热搜，一些厦门市民跟风尝试。记者了解到，生酮饮食最初是治疗<span style=\"font-size: 16px;\">难治性癫痫</span>的医疗手段，通过极低碳水、高脂肪、适量蛋白质的摄入，让身体从葡萄糖供能转为酮体供能，模拟饥饿状态。</p><p style=\"text-align: left;\">“生酮饮食短期减重效果明显，但绝非普通市民的减肥捷径。”厦门弘爱医院临床营养科主任刘燕表示，<span style=\"font-size: 16px;\">国家卫生健康委</span>已明确不推荐普通人群采用生酮饮食减肥。她解释，短期减重多为水分和糖原流失，并非真正减脂，长期维持会引发多种健康问题，“碳水摄入不足会导致大脑能量供给匮乏，出现记忆力下降、情绪暴躁等问题；蔬菜、水果摄入减少易引发<span style=\"font-size: 16px;\">维生素</span>、<span style=\"font-size: 16px;\">膳食纤维</span>缺乏，增加<span style=\"font-size: 16px;\">脱发</span>、贫血风险；过量摄入饱和脂肪还会加重肝肾、心血管负担，甚至诱发<span style=\"font-size: 16px;\">酮症酸中毒</span>”。</p><p style=\"text-align: left;\">刘燕认为，生酮饮食属于特殊医疗饮食，仅适用于难治性癫痫患者等特定人群，且需在医生全程监控下进行，普通人群切勿盲目尝试。“在追求健康生活的道路上，科学饮食与合理运动应成为我们共同的目标。如果确需生酮饮食，一定要在专业评估指导下进行。”</p>', '3月4日是世界肥胖日，如何应对肥胖问题引发广泛关注。喝苹果醋“刮油”、“补钾消水肿”、生酮饮食（极低碳水、适量蛋白质、高脂肪，让身体不靠糖供能，转而燃烧脂肪产生酮体的饮食方式）等网红减重法在社交平台刷屏，其中“补钾消水肿”更是成为热门话题。记者联系上专业医生，剖析网红减重法的误区，科普生酮饮食的适用边界，为市民春节节后科学减重提供指南。', '2026-01-05 19:21:30');
INSERT INTO `health_news` VALUES (15, 5, '/api/v1.0/self-health-api/file/getFile?fileName=17727779922141.webp', '清淡的晚餐可以做什么？ ', '<p style=\"text-align: left;\">在忙碌的生活中，晚餐往往是一天中最为重要的一餐。它不仅关系到我们的身体健康，还影响着我们的心情和精神状态。因此，选择一顿清淡的晚餐，既能满足我们对美食的追求，又能照顾到健康的需求。那么，清淡的晚餐可以做些什么呢？</p><p style=\"text-align: left;\">首先，蔬菜沙拉是一个不错的选择。新鲜的蔬菜搭配上一些坚果或者低脂的奶酪，既营养又美味。此外，还可以加入一些煮熟的鸡胸肉或者豆腐，增加蛋白质的摄入。这样一份简单的沙拉，不仅清爽可口，还能提供丰富的维生素和矿物质。</p><p style=\"text-align: left;\">其次，蒸鱼是一道非常健康的菜肴。鱼肉富含优质蛋白质和不饱和脂肪酸，有助于降低胆固醇。在烹饪时，可以选择清蒸的方式，避免过多的油脂。搭配一些蒸熟的蔬菜，如胡萝卜、西兰花等，既能增加口感，又能补充各种营养素。</p><p style=\"text-align: left;\">再者，汤品也是一个不错的选择。一碗清淡的鸡汤或者蔬菜汤，既能暖身又能补充水分。在制作汤品时，尽量使用新鲜的食材，避免使用过多的调味料。同时，也可以加入一些豆腐或者蘑菇等食材，增加汤品的营养价值。</p><p style=\"text-align: center;\"><img src=\"https://q8.itc.cn/images01/20260103/f688e93888bb4c689be41fcbbaf6e48b.jpeg\" alt=\"\" data-href=\"\" style=\"height: auto;\"></p><p style=\"text-align: left;\">最后，水果也是晚餐的好选择。新鲜的水果富含维生素和纤维，有助于消化和排毒。在晚餐后吃一个苹果或者橙子，既能满足口腹之欲，又能保持身体的健康。</p><p style=\"text-align: left;\">总之，一顿清淡的晚餐，不仅可以让我们享受美食，还能照顾到我们的健康需求。无论是蔬菜沙拉、蒸鱼、汤品还是水果，都是非常好的选择。只要我们用心去准备，就能做出一顿美味又健康的晚餐。</p>', '清淡的晚餐可以做什么？ ', '2026-01-05 19:22:33');
INSERT INTO `health_news` VALUES (16, 5, '/api/v1.0/self-health-api/file/getFile?fileName=17727781199801.webp', '近视患者看过来！这几类食物对眼睛好，不妨多吃点！ ', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>深色蔬菜：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">深色蔬菜，如菠菜、花椰菜和甜菜等富含叶黄素和玉米黄素。这两种抗氧化剂有能力保护眼睛免受自由基的损害。自由基是一种能够破坏细胞稳定性的分子，过多的自由基能引起细胞老化和疾病的发生。叶黄素和玉米黄素具有对抗自由基的特性，可以帮助保护眼睛中的细胞，特别是视网膜的细胞。这两种营养素也有助于防止黄斑变性，这是一种与年龄相关的疾病，能导致中心视力的丧失。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>富含维生素C的水果：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">柑橘类水果、草莓、猕猴桃等都是维生素C的优质来源。维生素C是一种强力的抗氧化剂，可以帮助身体对抗自由基的损害。对于眼睛来说，维生素C可以帮助保护视网膜和晶状体的健康，这两部分都对的视力至关重要。长期摄取足够的维生素C，可以帮助防止白内障和视网膜退化的发生，同时能帮助延缓视力的下降。</span></p><p style=\"text-align: left;\"><img src=\"https://q9.itc.cn/q_70/images03/20260306/a1f083681a2b42afab6dce3d464d0b6a.jpeg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>鱼类：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">富含Omega-3脂肪酸的鱼类，如鲑鱼、金枪鱼和鲭鱼等，这些鱼类对眼睛的健康有很大的好处。Omega-3脂肪酸可以帮助改善眼睛的润滑度，有助于预防干眼症，这是一种常见的眼部不适症状。Omega-3脂肪酸还可以帮助保护视网膜的健康，防止视网膜疾病的发生。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>鸡蛋：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">鸡蛋中的蛋黄富含叶黄素和玉米黄素，这两种营养素对眼睛好。它们可以帮助保护眼睛免受自由基的伤害，保护视网膜的健康。它们还可以帮助防止黄斑变性的发生，保护的中心视力。</span></p><p style=\"text-align: left;\"><img src=\"https://q0.itc.cn/q_70/images03/20260306/1a499a6fba6749e99a4eded7ae4e94c0.jpeg\" alt=\"\" data-href=\"\" style=\"width: 100%;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>坚果和种子：</strong></span></p><p style=\"text-align: justify;\"><span style=\"font-size: 16px;\">像核桃、亚麻籽、奇亚籽等坚果和种子富含Omega-3脂肪酸和维生素E，这些营养素对眼睛的健康也是至关重要的。Omega-3脂肪酸和维生素E都是强力的抗氧化剂，可以帮助保护眼睛免受自由基的损害。特别是维生素E，它可以帮助防止眼睛的氧化损伤，有助于防止白内障和黄斑变性的发生。</span></p>', '据调查报告显示，\n\n近年来我国的近视眼年龄越来越低龄。\n\n很多小孩在很小的年纪\n\n就已经患上近视眼。\n\n因此在生活中我们一定要\n\n多吃一些保护视力的食物！', '2026-01-05 19:24:06');

-- ----------------------------
-- Table structure for health_record
-- ----------------------------
DROP TABLE IF EXISTS `health_record`;
CREATE TABLE `health_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用户健康记录表主键ID，自增',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `health_model_id` int NULL DEFAULT NULL COMMENT '健康模型ID，外键，关联的是健康模型表',
  `value` double NULL DEFAULT NULL COMMENT '记录的值',
  `create_time` datetime NULL DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 675 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '健康记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of health_record
-- ----------------------------
