-- ----------------------------
-- Table structure for recipe
-- ----------------------------
DROP TABLE IF EXISTS `recipe`;
CREATE TABLE `recipe`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '食谱表主键ID，自增',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '食谱名',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '封面',
  `type_id` int NULL DEFAULT NULL COMMENT '食谱类别ID，外键，通过后端枚举类进行管理',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '内容',
  `user_id` int NULL DEFAULT NULL COMMENT '用户ID，外键，关联的是用户表',
  `is_public` tinyint(1) NULL DEFAULT NULL COMMENT '是否是公开食谱，如果是公开食谱，需要管理员审核，私人食谱就是能自己用',
  `is_audit` tinyint(1) NULL DEFAULT NULL COMMENT '是否已经审核',
  `create_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '食谱信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of recipe
-- ----------------------------
INSERT INTO `recipe` VALUES (17, '香煎鸡胸肉', '/api/v1.0/self-health-api/file/getFile?fileName=17729639858161.jpg', 2, '<h3>食材（1人份）</h3><ul><li>鸡胸肉 200g</li><li>橄榄油 5g</li><li>盐 2g</li><li>黑胡椒 1g</li><li>蒜末 少量</li></ul><h3>做法</h3><ol><li>鸡胸肉洗净后从中间片开，使厚度均匀。</li><li>加入盐、黑胡椒、蒜末腌制约15分钟。</li><li>平底锅加热，放入橄榄油。</li><li>中火煎鸡胸肉，每面约3-4分钟。</li><li>表面微焦且内部熟透即可出锅。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约320 kcal</li><li>蛋白质：约42 g</li><li>脂肪：约12 g</li><li>碳水化合物：约2 g</li></ul><p>特点：高蛋白、低碳水，非常适合力量训练后的蛋白补充。</p>', 64, 1, 1, '2026-03-08 18:00:55');
INSERT INTO `recipe` VALUES (21, '西兰花牛肉', '/api/v1.0/self-health-api/file/getFile?fileName=17729675971392.jpg', 2, '<h3>食材</h3><ul><li>牛里脊 150g</li><li>西兰花 200g</li><li>生抽 10ml</li><li>料酒 5ml</li><li>玉米淀粉 5g</li><li>植物油 8g</li><li>蒜 2瓣</li></ul><h3>做法</h3><ol><li>牛肉切薄片，加入生抽、料酒、淀粉腌制10分钟。</li><li>西兰花切小朵，沸水焯1分钟。</li><li>锅中加油，爆香蒜末。</li><li>放入牛肉快速翻炒至变色。</li><li>加入西兰花翻炒1-2分钟即可。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约360 kcal</li><li>蛋白质：约35 g</li><li>脂肪：约18 g</li><li>碳水：约12 g</li></ul><p>特点：蛋白质丰富，同时补充膳食纤维与维生素C。</p>', 59, 1, 1, '2026-03-08 19:00:14');
INSERT INTO `recipe` VALUES (22, '三文鱼牛油果沙拉', '/api/v1.0/self-health-api/file/getFile?fileName=17729681000733.jpg', 2, '<h3>食材</h3><ul><li>三文鱼 120g</li><li>牛油果 1个（约150g）</li><li>生菜 80g</li><li>小番茄 50g</li><li>橄榄油 10ml</li><li>柠檬汁 5ml</li><li>黑胡椒 少量</li></ul><h3>做法</h3><ol><li>三文鱼平底锅煎熟或使用烟熏三文鱼。</li><li>牛油果去皮切块。</li><li>生菜洗净沥干，小番茄对半切。</li><li>将所有食材放入碗中。</li><li>淋橄榄油和柠檬汁，撒黑胡椒拌匀。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约520 kcal</li><li>蛋白质：约28 g</li><li>脂肪：约36 g</li><li>碳水：约18 g</li></ul><p>特点：富含Omega-3脂肪酸，有助于肌肉恢复。</p>', 60, 1, 1, '2026-03-08 19:08:34');
INSERT INTO `recipe` VALUES (23, '鸡蛋燕麦碗', '/api/v1.0/self-health-api/file/getFile?fileName=17729685261964.jpg', 2, '<h3>食材</h3><ul><li>燕麦片 50g</li><li>牛奶 200ml</li><li>鸡蛋 2个</li><li>蓝莓 30g</li><li>蜂蜜 5g</li></ul><h3>做法</h3><ol><li>锅中加入牛奶和燕麦，小火煮5分钟。</li><li>鸡蛋煮熟后切半。</li><li>将燕麦盛入碗中。</li><li>放入鸡蛋和蓝莓。</li><li>淋少量蜂蜜即可。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约420 kcal</li><li>蛋白质：约25 g</li><li>脂肪：约14 g</li><li>碳水：约50 g</li></ul><p>特点：碳水与蛋白质搭配，适合作为运动前或早餐。</p>', 61, 1, 1, '2026-03-08 19:15:42');
INSERT INTO `recipe` VALUES (24, '黑椒牛排', '/api/v1.0/self-health-api/file/getFile?fileName=17729685887465.jpg', 2, '<h3>食材</h3><ul><li>牛排 200g</li><li>橄榄油 5g</li><li>盐 2g</li><li>黑胡椒 2g</li></ul><h3>做法</h3><ol><li>牛排提前30分钟从冰箱取出。</li><li>表面撒盐和黑胡椒。</li><li>平底锅加热后放橄榄油。</li><li>大火煎每面约2-3分钟。</li><li>静置3分钟再切片。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约430 kcal</li><li>蛋白质：约40 g</li><li>脂肪：约28 g</li><li>碳水：0 g</li></ul><p>特点：优质动物蛋白来源，含铁和B族维生素。</p>', 62, 1, 1, '2026-03-08 19:16:52');
INSERT INTO `recipe` VALUES (25, '清蒸鸡胸肉', '/api/v1.0/self-health-api/file/getFile?fileName=17729686966796.jpg', 1, '<h3>食材</h3><ul><li>鸡胸肉 150g</li><li>姜片 3片</li><li>盐 2g</li><li>葱花 少量</li></ul><h3>做法</h3><ol><li>鸡胸肉切块。</li><li>放入盘中加入姜片和少量盐。</li><li>蒸锅水开后蒸约15分钟。</li><li>出锅撒葱花。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约240 kcal</li><li>蛋白质：约35 g</li><li>脂肪：约5 g</li><li>碳水：约1 g</li></ul><p>特点：低脂高蛋白，非常适合减脂期。</p>', 63, 1, 1, '2026-03-08 19:18:28');
INSERT INTO `recipe` VALUES (26, '凉拌黄瓜', '/api/v1.0/self-health-api/file/getFile?fileName=17729687439467.jpg', 1, '<h3>食材</h3><ul><li>黄瓜 300g</li><li>蒜末 1瓣</li><li>香醋 10ml</li><li>盐 2g</li><li>香油 3ml</li></ul><h3>做法</h3><ol><li>黄瓜拍碎切段。</li><li>加入蒜末、盐。</li><li>倒入香醋和香油。</li><li>搅拌均匀即可。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约90 kcal</li><li>蛋白质：约3 g</li><li>脂肪：约3 g</li><li>碳水：约12 g</li></ul><p>特点：热量低、含水量高，增加饱腹感。</p>', 63, 1, 1, '2026-03-08 19:19:13');
INSERT INTO `recipe` VALUES (27, '西红柿鸡蛋汤', '/api/v1.0/self-health-api/file/getFile?fileName=17729687852018.jpg', 1, '<h3>食材</h3><ul><li>西红柿 2个（约200g）</li><li>鸡蛋 1个</li><li>盐 2g</li><li>香油 2ml</li></ul><h3>做法</h3><ol><li>西红柿切块。</li><li>锅中加水煮沸。</li><li>放入西红柿煮2分钟。</li><li>缓慢倒入蛋液形成蛋花。</li><li>加盐和香油即可。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约120 kcal</li><li>蛋白质：约8 g</li><li>脂肪：约6 g</li><li>碳水：约10 g</li></ul><p>特点：低热量、富含番茄红素。</p>', 59, 1, 1, '2026-03-08 19:19:53');
INSERT INTO `recipe` VALUES (28, '清炒西兰花', '/api/v1.0/self-health-api/file/getFile?fileName=17729688195849.jpg', 1, '<h3>食材</h3><ul><li>西兰花 250g</li><li>蒜 2瓣</li><li>橄榄油 5g</li><li>盐 2g</li></ul><h3>做法</h3><ol><li>西兰花掰小朵。</li><li>沸水焯1分钟。</li><li>锅中放橄榄油爆香蒜末。</li><li>加入西兰花翻炒2分钟。</li><li>加盐即可。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约110 kcal</li><li>蛋白质：约7 g</li><li>脂肪：约5 g</li><li>碳水：约12 g</li></ul><p>特点：富含膳食纤维和维生素C。</p>', 64, 1, 1, '2026-03-08 19:20:31');
INSERT INTO `recipe` VALUES (29, '鸡胸肉蔬菜沙拉', '/api/v1.0/self-health-api/file/getFile?fileName=177296886177310.jpg', 1, '<h3>食材</h3><ul><li>鸡胸肉 120g</li><li>生菜 100g</li><li>小番茄 50g</li><li>黄瓜 50g</li><li>橄榄油 5ml</li><li>黑胡椒 少量</li></ul><h3>做法</h3><ol><li>鸡胸肉煮熟或煎熟后切块。</li><li>生菜洗净撕小块。</li><li>小番茄对半切。</li><li>将所有食材放入碗中。</li><li>加橄榄油和黑胡椒拌匀。</li></ol><h3>营养成分（约）</h3><ul><li>热量：约210 kcal</li><li>蛋白质：约28 g</li><li>脂肪：约8 g</li><li>碳水：约10 g</li></ul><p>特点：低热量、高蛋白、饱腹感强。</p>', 64, 1, 1, '2026-03-08 19:21:10');
INSERT INTO `recipe` VALUES (30, '私人食谱测试', '/api/v1.0/self-health-api/file/getFile?fileName=17729689366611.webp', 1, '<p>111</p>', 64, 0, 0, '2026-03-08 19:22:26');

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户编号',
  `account` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户账号',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户昵称',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户密码',
  `avatar` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用户头像',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用户邮箱',
  `role` int NULL DEFAULT NULL COMMENT '用户角色',
  `gender` tinyint(1) NULL DEFAULT NULL COMMENT '性别：1-女；2-男；',
  `birthday` date NULL DEFAULT NULL COMMENT '生日',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `create_time` datetime NULL DEFAULT NULL COMMENT '用户注册时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

